import { Request } from 'express';

export interface TenantContext {
  /** Validated organization ID extracted from JWT claims */
  organizationId: string;
  /** User ID from JWT sub claim */
  userId: string;
  /** User roles within this organization */
  roles: string[];
  /** JWT issued-at timestamp for audit correlation */
  issuedAt: number;
  /** JWT expiration timestamp */
  expiresAt: number;
}

export interface TenantRequest extends Request {
  /** Set exclusively by TenantScopeMiddleware — never read from body/query */
  tenantContext: TenantContext;
}

/**
 * Type guard to verify a request has been through TenantScopeMiddleware.
 * Throws if called on an un-decorated request (programming error).
 */
export function assertTenantContext(
  req: Request,
): asserts req is TenantRequest {
  const tenantReq = req as TenantRequest;
  if (
    !tenantReq.tenantContext ||
    typeof tenantReq.tenantContext.organizationId !== 'string' ||
    tenantReq.tenantContext.organizationId.trim() === ''
  ) {
    throw new Error(
      'TenantContext missing — TenantScopeMiddleware must run before this handler',
    );
  }
}

/**
 * Resource ownership check result — carries denial reason for audit logging.
