 * Auth domain types.
 *
 * OrganizationContext is the central security primitive: every request that
 * passes authentication is stamped with one, and every repository call
 * requires it.  This makes it structurally impossible to call a scoped
 * repository without first going through the auth middleware.
 */

export type UserRole = 'owner' | 'admin' | 'member' | 'viewer';

/**
 * The decoded, verified payload extracted from the JWT.
 * Fields must match what the auth server embeds in access tokens.
 */
export interface JwtPayload {
  /** Subject — the user's UUID */
  sub: string;
  /** The organization UUID this token is scoped to */
  org_id: string;
  /** User's display email — informational only, never used for authz */
  email: string;
  /** Role within the organization */
  role: UserRole;
  /** Issued-at (Unix seconds) */
  iat: number;
  /** Expiry (Unix seconds) */
  exp: number;
  /** JWT ID — used for revocation checks */
  jti: string;
}

/**
 * The minimal security context attached to every authenticated request.
 * Consumed by middleware and passed down to services/repositories.
 */
export interface OrganizationContext {
  /** Authenticated user UUID */
  readonly userId: string;
  /** Organization UUID — every DB query is scoped to this */
  readonly organizationId: string;
  /** User role — used for permission checks within the org */
  readonly role: UserRole;
  /** JWT ID for audit correlation */
  readonly jti: string;
}

/**
 * Augment Express Request so TypeScript knows about our custom properties.
 */
declare global {
  namespace Express {
    interface Request {
      /**
       * Set by `tenant-scope.middleware` after JWT verification.
       * Guaranteed to be present on any route that uses the middleware chain:
       *   authenticate → tenantScope
       */
      orgContext: OrganizationContext;
    }
  }
}
