/**
 * Abstract base class for all validators.
 * Provides result construction helpers and shared utilities.
 */
export abstract class BaseValidator<TInput, TOutput = TInput> {
  protected abstract readonly validatorName: string;

  abstract validate(
    input: TInput,
    field?: string
  ): ValidationResult<TOutput>;

  // ─── Result builders ────────────────────────────────────────────────────────

  protected ok(
    value: TOutput,
    warnings: ValidationWarning[] = []
  ): ValidationResult<TOutput> {
    return { success: true, value, warnings };
  }

  protected fail(
    errors: ValidationError[],
    warnings: ValidationWarning[] = []
  ): ValidationResult<TOutput> {
    return { success: false, errors, warnings };
  }

  protected error(
    code: ValidationError['code'],
    message: string,
    extra: Partial<Omit<ValidationError, 'code' | 'message'>> = {}
  ): ValidationError {
    return { code, message, ...extra };
  }

  // ─── String utilities ───────────────────────────────────────────────────────

  /**
   * Normalise a string: Unicode NFC, collapse whitespace, trim.
   * NFC normalization closes many unicode-bypass attack vectors
   * (e.g., full-width characters that look like ASCII operators).
   */
  protected normalize(value: string): string {
    return value
      .normalize('NFC')
      .replace(/[\u200B-\u200D\uFEFF]/g, '') // strip zero-width chars
      .trim();
  }

  /**
   * Decode a string multiple times to catch double/triple-encoded payloads.
   * Stops when two consecutive decodes produce the same result.
   */
  protected fullyDecode(value: string): string {
    let current = value;
    for (let i = 0; i < 5; i++) {
      let next: string;
      try {
        next = decodeURIComponent(current.replace(/\+/g, ' '));
      } catch {
        // If decoding fails, the string is not further URL-encoded
        break;
      }
      if (next === current) {
        break;
      }
      current = next;
    }
    return current;
  }

  /**
   * Decode HTML entities to their character equivalents.
   * Used to detect payloads that hide behind entity encoding.
   */
  protected decodeHtmlEntities(value: string): string {
    return value
      .replace(/&amp;/gi, '&')
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&quot;/gi, '"')
      .replace(/&#x27;/gi, "'")
      .replace(/&#x2F;/gi, '/')
      .replace(/&#(\d+);/g, (_, dec: string) =>
        String.fromCharCode(parseInt(dec, 10))
      )
      .replace(/&#x([0-9a-fA-F]+);/g, (_, hex: string) =>
        String.fromCharCode(parseInt(hex, 16))
      );
  }

  /**
   * Prepare a string for injection detection by normalizing and fully decoding.
   */
  protected prepareForDetection(value: string): string {
    const decoded = this.fullyDecode(this.decodeHtmlEntities(value));
    return this.normalize(decoded).toLowerCase();
  }
}
