 * Typed error hierarchy for the validation/sanitization pipeline.
 *
 * All errors carry a `code` for programmatic handling, a human-readable
 * `message`, and an optional `field` path for nested structures.
 */

export type ValidationErrorCode =
  | 'FIELD_REQUIRED'
  | 'TYPE_MISMATCH'
  | 'LENGTH_EXCEEDED'
  | 'LENGTH_BELOW_MINIMUM'
  | 'PATTERN_MISMATCH'
  | 'VALUE_NOT_IN_ENUM'
  | 'NUMERIC_OUT_OF_RANGE'
  | 'INVALID_URL_SCHEME'
  | 'INVALID_EMAIL_FORMAT'
  | 'CONTROL_CHARACTERS_DETECTED';

export type SanitizationErrorCode =
  | 'DISALLOWED_SQL_OPERATOR'
  | 'DISALLOWED_SQL_FIELD'
  | 'SQL_INJECTION_PATTERN_DETECTED'
  | 'PROTOTYPE_POLLUTION_ATTEMPT'
  | 'DISALLOWED_HTML_TAG'
  | 'DISALLOWED_ATTRIBUTE'
  | 'DANGEROUS_URI_SCHEME'
  | 'DANGEROUS_CSS_EXPRESSION'
  | 'NULL_BYTE_DETECTED'
  | 'UNICODE_NORMALIZATION_BLOCKED';

export type PipelineErrorCode = ValidationErrorCode | SanitizationErrorCode | 'PIPELINE_STAGE_FAILED';

/** Base class for all pipeline errors. */
export class PipelineError extends Error {
  public readonly code: PipelineErrorCode;
  public readonly field: string | undefined;
  public readonly context: Record<string, unknown>;

  constructor(
    code: PipelineErrorCode,
    message: string,
    field?: string,
    context: Record<string, unknown> = {},
  ) {
    super(message);
    this.name = 'PipelineError';
    this.code = code;
    this.field = field;
    this.context = context;
    // Restore prototype chain (TypeScript + Error subclassing)
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/** Thrown when a value fails a validation rule. */
export class ValidationError extends PipelineError {
  public readonly validationCode: ValidationErrorCode;

  constructor(
    code: ValidationErrorCode,
    message: string,
    field?: string,
    context: Record<string, unknown> = {},
  ) {
    super(code, message, field, context);
    this.name = 'ValidationError';
    this.validationCode = code;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/** Thrown when a value contains a security-relevant pattern. */
export class SanitizationError extends PipelineError {
  public readonly sanitizationCode: SanitizationErrorCode;

  constructor(
    code: SanitizationErrorCode,
    message: string,
    field?: string,
    context: Record<string, unknown> = {},
  ) {
    super(code, message, field, context);
    this.name = 'SanitizationError';
    this.sanitizationCode = code;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/** Aggregates multiple errors from a single pipeline run. */
export class AggregatedValidationError extends Error {
  public readonly errors: ReadonlyArray<PipelineError>;

  constructor(errors: ReadonlyArray<PipelineError>) {
    const summary = errors.map((e) => `[${e.code}] ${e.field ? `${e.field}: ` : ''}${e.message}`).join('; ');
    super(`Validation failed with ${errors.length} error(s): ${summary}`);
    this.name = 'AggregatedValidationError';
    this.errors = errors;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}
