/** Characters that must be HTML-entity-encoded to prevent XSS. */
const HTML_ENTITY_MAP: Readonly<Record<string, string>> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#x27;',
  '/': '&#x2F;',
  '`': '&#x60;',
  '=': '&#x3D;',
};

/**
 * Encodes all HTML-sensitive characters in a string.
 * Suitable for injecting content into HTML text nodes and attribute values.
 */
export function htmlEncode(input: string): string {
  return input.replace(/[&<>"'`=/]/g, (char) => HTML_ENTITY_MAP[char] ?? char);
}

/**
 * Decodes common HTML entities back to their characters.
 * Used internally during sanitization to detect encoded attack patterns.
 */
export function htmlDecode(input: string): string {
  return input
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#x27;/gi, "'")
    .replace(/&#x2F;/gi, '/')
    .replace(/&#x60;/gi, '`')
    .replace(/&#x3D;/gi, '=')
    .replace(/&#(\d+);/g, (_, dec: string) => String.fromCharCode(parseInt(dec, 10)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex: string) => String.fromCharCode(parseInt(hex, 16)));
}

/**
 * Strips all null bytes (\x00) from a string.
 * Null bytes can be used to truncate strings in C-based systems
 * or bypass certain validation checks.
 */
export function stripNullBytes(input: string): string {
  // eslint-disable-next-line no-control-regex
  return input.replace(/\x00/g, '');
}

/**
 * Strips ASCII control characters (0x01–0x1F, 0x7F) except for
 * horizontal tab (0x09), newline (0x0A), and carriage return (0x0D),
 * which are legitimate in multi-line text fields.
 */
export function stripControlCharacters(input: string): string {
  // eslint-disable-next-line no-control-regex
  return input.replace(/[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
}

/**
 * Normalizes a string to NFC Unicode normal form.
 * Prevents homoglyph and combining-character attacks where
 * visually identical characters bypass regex-based filters.
 */
export function normalizeUnicode(input: string): string {
  return input.normalize('NFC');
}

/**
 * Encodes a string for safe use in a URL component.
 * Wraps the standard encodeURIComponent but also handles edge cases.
 */
export function encodeUrlComponent(input: string): string {
  return encodeURIComponent(input);
}

